public boolean isPalindrome(ListNode head) {
        if (head == null) {
            return false;
        }
        ListNode fast = head, slow = head;
        while (fast != null && fast.next != null) {
            // 偶数情况slow 在第二部分的开头
            // 奇数情况slow 在正中间
            fast = fast.next.next;
            slow = slow.next;
        }
        ListNode p1 = slow;
        Stack<Integer> stack = new Stack<>();
        // 奇数情况 fast不会为空
        if (fast != null) {
            slow = slow.next;
        }
        while (slow != null) {
            stack.push(slow.val);
            slow = slow.next;
        }
        fast = head;
        while (fast != p1 && !stack.isEmpty()) {
            if (fast.val != stack.peek()) {
                return false;
            }
            stack.pop();
            fast = fast.next;
        }
        return stack.isEmpty();
    }

public boolean isPalindrome(ListNode head) {
        if (head == null) {
            return true;
        }
        ListNode mid = getMid(head);
        ListNode newHead = reverseList(mid);
        ListNode p1 = head, p2 = newHead;
        while (p2 != null) {
            if (p1.val != p2.val) {
                return false;
            }
            p1 = p1.next;
            p2 = p2.next;
        }
        return true;
    }

    private ListNode reverseList(ListNode head) {
        if (head == null || head.next == null) {
            return head;
        }
        ListNode pre = null, cur = head;
        while (cur != null) {
            ListNode next = cur.next;
            cur.next = pre;
            pre = cur;
            cur = next;
        }
        return pre;
    }

    private ListNode getMid(ListNode head) {
        ListNode fast = head, slow = head;
        while (fast != null && fast.next != null) {
            fast = fast.next.next;
            slow = slow.next;
        }
        return slow;
    }

